import React, { useState } from 'react';
import { User, CreditCard, Clock, Search } from 'lucide-react';

const CitizenInfo = () => {
  const [selected, setSelected] = useState(null);

  return (
    <div className="animate-slot flex flex-col md:flex-row gap-10 h-full">
      {/* LIST */}
      <div className="w-full md:w-1/3 flex flex-col gap-4 overflow-y-auto pr-2">
        <input placeholder="SEARCH_CITIZEN..." className="bg-[#FDFAD8] border-[4px] border-[#47510B] p-4 rounded-full text-xs font-black uppercase mb-4 shadow-[4px_4px_0_0_#47510B]" />
        {[1, 2, 3, 4, 5].map(i => (
          <div key={i} onClick={() => setSelected(i)} className={`relative cursor-pointer group`}>
            <div className="absolute inset-0 bg-[#47510B] translate-x-1.5 translate-y-1.5 rounded-[25px]" />
            <div className={`relative p-5 border-[4px] border-[#47510B] rounded-[25px] flex items-center gap-4 transition-colors ${selected === i ? 'bg-[#FF5B03] text-white' : 'bg-white'}`}>
              <div className="w-10 h-10 rounded-full bg-[#A1AED1] border-2 border-[#47510B]" />
              <span className="font-black italic uppercase text-sm tracking-tighter">Citizen_ID_0{i}</span>
            </div>
          </div>
        ))}
      </div>

      {/* DETAILS PANEL */}
      <div className="flex-grow relative">
        <div className="absolute inset-0 bg-[#47510B] translate-x-3 translate-y-3 rounded-[40px]" />
        <div className="relative h-full bg-[#FDFAD8] border-[6px] border-[#47510B] rounded-[40px] p-10">
          {!selected ? (
            <div className="h-full flex flex-col items-center justify-center opacity-20 italic font-black">SELECT_CITIZEN_RECORD</div>
          ) : (
            <div className="flex flex-col gap-8">
              <div className="flex justify-between items-start">
                <h2 className="text-5xl font-[1000] italic text-[#47510B] uppercase">Citizen_Profile_{selected}</h2>
                <span className="bg-[#CAD23C] px-4 py-2 border-[4px] border-[#47510B] rounded-xl font-black italic shadow-[4px_4px_0_0_#47510B]">STATUS: PREMIUM</span>
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div className="bg-white border-[4px] border-[#47510B] p-6 rounded-[30px] shadow-[6px_6px_0_0_#47510B]">
                  <p className="text-[10px] font-black opacity-40 uppercase mb-2">Billing_History</p>
                  <p className="font-black text-[#AB1717]">PAID // MAR 2026</p>
                </div>
                <div className="bg-white border-[4px] border-[#47510B] p-6 rounded-[30px] shadow-[6px_6px_0_0_#47510B]">
                  <p className="text-[10px] font-black opacity-40 uppercase mb-2">Collection_Success</p>
                  <p className="font-black text-[#47510B]">98.2% ACCURACY</p>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};
